actions.code:
type PopoverRootActions = {
    unmount: () => void;
    close: () => void;
};

changeEventDetails.code:
type PopoverRootChangeEventDetails = ({
    reason: 'trigger-hover';
    event: MouseEvent;
} | {
    reason: 'trigger-focus';
    event: FocusEvent;
} | {
    reason: 'trigger-press';
    event: MouseEvent | PointerEvent | TouchEvent | KeyboardEvent;
} | {
    reason: 'outside-press';
    event: MouseEvent | PointerEvent | TouchEvent;
} | {
    reason: 'escape-key';
    event: KeyboardEvent;
} | {
    reason: 'close-press';
    event: MouseEvent | PointerEvent | KeyboardEvent;
} | {
    reason: 'focus-out';
    event: FocusEvent | KeyboardEvent;
} | {
    reason: 'imperative-action';
    event: Event;
} | {
    reason: 'none';
    event: Event;
}) & {
    cancel: () => void;
    allowPropagation: () => void;
    isCanceled: boolean;
    isPropagationAllowed: boolean;
    trigger: Element | undefined;
    preventUnmountOnClose: () => void;
};

state.code:
type PopoverTriggerState = {
    disabled: boolean;
    open: boolean;
};

type PopoverBackdropState = {
    open: boolean;
    transitionStatus: TransitionStatus;
};

type PopoverPositionerState = {
    open: boolean;
    side: Side;
    align: Align;
    anchorHidden: boolean;
    instant: string | undefined;
};

type PopoverPopupState = {
    open: boolean;
    side: Side;
    align: Align;
    transitionStatus: TransitionStatus;
    instant: 'dismiss' | 'click' | 'focus' | 'trigger-change' | undefined;
};

type PopoverArrowState = {
    open: boolean;
    side: Side;
    align: Align;
    uncentered: boolean;
};

type PopoverViewportState = {
    activationDirection: string | undefined;
    transitioning: boolean;
    instant: 'dismiss' | 'click' | 'focus' | 'trigger-change' | undefined;
};

